def _check_delimiter(delimiter):
    """Rule 9: the delimiter is exactly one character, not '"', '\\n' or '\\r'."""
    if not isinstance(delimiter, str) or len(delimiter) != 1:
        raise ValueError("delimiter must be exactly one character")
    if delimiter in ('"', "\n", "\r"):
        raise ValueError("delimiter must not be a quote or a line break")


def parse_record(text, delimiter=","):
    """Split one delimited record into its fields. See TASK.md."""
    _check_delimiter(delimiter)
    if not isinstance(text, str):
        raise ValueError("text must be a str")

    n = len(text)
    fields = []
    pos = 0
    while True:
        # Parse one field starting at pos; end_pos is the index of the
        # delimiter that ends it, or n if it ends the text.
        if pos < n and text[pos] == '"':
            # Rule 2: quoted field.
            pos += 1
            buf = []
            while True:
                if pos >= n:
                    raise ValueError("unclosed quoted field")
                c = text[pos]
                if c == '"':
                    if pos + 1 < n and text[pos + 1] == '"':
                        buf.append('"')
                        pos += 2
                        continue
                    pos += 1  # closing quote
                    break
                buf.append(c)
                pos += 1
            # Rule 3: closing quote must be followed by delimiter or end.
            if pos < n and text[pos] != delimiter:
                raise ValueError("text after closing quote")
            field = "".join(buf)
            end_pos = pos
        else:
            # Rule 4 and 5: unquoted field.
            start = pos
            while pos < n and text[pos] != delimiter:
                c = text[pos]
                if c == '"':
                    raise ValueError('quote inside unquoted field')
                if c in ("\n", "\r"):
                    raise ValueError("line break outside quoted field")
                pos += 1
            field = text[start:pos]
            end_pos = pos

        fields.append(field)
        if end_pos >= n:
            break
        pos = end_pos + 1  # skip the delimiter; a trailing one yields an empty field
    return fields


def format_record(fields, delimiter=","):
    """Write fields as one delimited record. See TASK.md."""
    _check_delimiter(delimiter)
    if isinstance(fields, str):
        raise ValueError("fields must be a sequence of str")
    try:
        fields = list(fields)
    except TypeError:
        raise ValueError("fields must be a sequence of str")
    if len(fields) == 0:
        raise ValueError("at least one field is required")

    out = []
    for f in fields:
        # Rule 7: every field must be a str.
        if not isinstance(f, str):
            raise ValueError("every field must be a str")
        # Rule 6: quote when needed, doubling inner quotes.
        needs_quotes = (
            delimiter in f
            or '"' in f
            or "\n" in f
            or "\r" in f
            or f.startswith(" ")
            or f.endswith(" ")
        )
        if needs_quotes:
            out.append('"' + f.replace('"', '""') + '"')
        else:
            out.append(f)
    return delimiter.join(out)
